import { getJson, postJson } from "./http";
import type { FormConfig, FormValues } from "../forms/types";

export function getFormConfig(formId: string): Promise<FormConfig> {
  return getJson<FormConfig>(`/api/forms/${encodeURIComponent(formId)}`);
}

export function submitForm(config: FormConfig, values: FormValues): Promise<{ id: string }> {
  return postJson<{ id: string }>(config.submitUrl, values);
}

