import { useEffect, useState, type FormEvent } from "react";
import { getFormConfig, submitForm } from "../api/forms";
import { FieldInput } from "./FieldInput";
import { validate, type FieldErrors } from "./validate";
import type { FormConfig, FormValues } from "./types";

type Status = "loading" | "ready" | "submitting" | "failed";

interface DynamicFormProps {
  formId: string;
  onSubmitted: (id: string) => void;
}

export function DynamicForm({ formId, onSubmitted }: DynamicFormProps) {
  const [config, setConfig] = useState<FormConfig | null>(null);
  const [values, setValues] = useState<FormValues>({});
  const [errors, setErrors] = useState<FieldErrors>({});
  const [status, setStatus] = useState<Status>("loading");

  useEffect(() => {
    let cancelled = false;
    setStatus("loading");
    getFormConfig(formId).then(
      (cfg) => {
        if (cancelled) return;
        setConfig(cfg);
        setValues(Object.fromEntries(cfg.fields.map((f) => [f.name, f.defaultValue])));
        setErrors({});
        setStatus("ready");
      },
      () => {
        if (!cancelled) setStatus("failed");
      },
    );
    return () => {
      cancelled = true;
    };
  }, [formId]);

  if (status === "loading") return <p>Loading form...</p>;
  if (status === "failed" || config === null) return <p role="alert">This form could not be loaded.</p>;
  const cfg = config;

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const found = validate(cfg.fields, values);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    setStatus("submitting");
    try {
      const { id } = await submitForm(cfg, values);
      onSubmitted(id);
    } catch {
      setStatus("ready");
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h2>{cfg.title}</h2>
      {cfg.fields.map((field) => (
        <FieldInput
          key={field.name}
          field={field}
          value={values[field.name]}
          error={errors[field.name]}
          onChange={(v) => setValues((prev) => ({ ...prev, [field.name]: v }))}
        />
      ))}
      <button type="submit" disabled={status === "submitting"}>
        {cfg.submitLabel ?? "Submit"}
      </button>
    </form>
  );
}

