import type { FieldConfig } from "./types";

interface FieldInputProps {
  field: FieldConfig;
  value: any;
  error?: string;
  onChange: (value: any) => void;
}

export function FieldInput({ field, value, error, onChange }: FieldInputProps) {
  const id = `field-${field.name}`;
  const step = field.step ?? 1;

  function renderControl() {
    switch (field.kind) {
      case "number":
        return (
          <div className="stepper">
            <button type="button" aria-label="Decrease" onClick={() => onChange(value - step)}>-</button>
            <input
              id={id}
              type="number"
              min={field.min}
              max={field.max}
              value={value ?? ""}
              onChange={(e) => onChange(e.target.value)}
            />
            <button type="button" aria-label="Increase" onClick={() => onChange(value + step)}>+</button>
          </div>
        );
      case "select":
        return (
          <select id={id} value={value ?? ""} onChange={(e) => onChange(e.target.value)}>
            <option value="" disabled>{field.placeholder ?? "Select..."}</option>
            {field.options!.map((o) => (
              <option key={o.value} value={o.value}>{o.label}</option>
            ))}
          </select>
        );
      case "checkbox":
        return (
          <input id={id} type="checkbox" checked={Boolean(value)} onChange={(e) => onChange(e.target.checked)} />
        );
      case "date":
        return <input id={id} type="date" value={value ?? ""} onChange={(e) => onChange(e.target.value)} />;
      default:
        return (
          <input
            id={id}
            type="text"
            placeholder={field.placeholder}
            value={value ?? ""}
            onChange={(e) => onChange(e.target.value)}
          />
        );
    }
  }

  return (
    <div className="field">
      <label htmlFor={id}>
        {field.label}
        {field.required && " *"}
      </label>
      {renderControl()}
      {field.helpText && <p className="help">{field.helpText}</p>}
      {error && <p className="error" role="alert">{error}</p>}
    </div>
  );
}

