import type { FieldConfig, FormValues } from "./types";

export type FieldErrors = Record<string, string>;

export function validate(fields: FieldConfig[], values: FormValues): FieldErrors {
  const errors: FieldErrors = {};
  for (const f of fields) {
    const v = values[f.name];
    const empty = v === undefined || v === "" || v === false;
    if (f.required && empty) {
      errors[f.name] = `${f.label} is required`;
      continue;
    }
    if (f.kind === "number" && !empty) {
      if (f.min !== undefined && v < f.min) errors[f.name] = `Minimum is ${f.min}`;
      if (f.max !== undefined && v > f.max) errors[f.name] = `Maximum is ${f.max}`;
    }
  }
  return errors;
}

